JOB_REGISTRY: dict[str, dict] = {}

@router.get("/reports/queue-jobs/{job_id}")
async def poll_queue_job(
    job_id: str,
    current_user: User = Depends(get_current_user)
):
    job = JOB_REGISTRY.get(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="Job not found")
    if job.get("user_id") != current_user.id and not current_user.is_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized access to report generation job")
    return {
        "job_id": job_id,
        "status": job["status"],
        "result": job.get("result")
    }
